// ─── File: src/main/java/com/bank/api/BankApiDemo.java ───
package com.bank.api;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class BankApiDemo {

    private static final Logger log = Logger.getLogger(BankApiDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountRepository accountRepo = new AccountRepository();
        TransactionRepository txnRepo = new TransactionRepository();

        // Same characters used across the project.
        accountRepo.save(new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        accountRepo.save(new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));

        // Seed 5 transactions so cursor pagination is visible.
        for (int i = 1; i <= 5; i++) {
            txnRepo.save(new Transaction("TXN-" + String.format("%05d", i),
                    "SAV2001", new BigDecimal(1000 * i), LocalDate.now()));
        }

        BankApiService service = new BankApiService(accountRepo, txnRepo, new IdempotencyStore());

        // 1 + 3. Error handling + versioning: read an account (v2 shape).
        AccountResponse acct = service.getAccount("SAV2001");
        log.info(() -> "GET /api/v2/accounts/SAV2001 -> " + acct);

        // 1. Error handling: missing account produces a ProblemDetail (404).
        try {
            service.getAccount("SAV9999");
        } catch (AccountNotFoundException ex) {
            log.warning(() -> "404 ProblemDetail -> " + ex.toProblemDetail());
        }

        // 2. Pagination: first page of 2, then follow the cursor.
        PageResponse page1 = service.listTransactions("SAV2001", null, 2);
        log.info(() -> "Page 1 -> " + page1);
        PageResponse page2 = service.listTransactions("SAV2001", page1.nextCursor(), 2);
        log.info(() -> "Page 2 -> " + page2);

        // 4. Idempotency: the same key retried moves the money only once.
        String key = "7f3b-rajesh-rent-oct";
        String first = service.transfer(key, "SAV2001", "CUR3001", new BigDecimal("50000"));
        String retry = service.transfer(key, "SAV2001", "CUR3001", new BigDecimal("50000"));
        log.info(() -> "Transfer first=" + first + " retry=" + retry
                + " (same result, money moved once)");
    }
}

// ─── Would be in model/Account.java in a real project ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    private int version; // internal column — never exposed in the DTO

    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }

    void debit(BigDecimal amount) {
        if (balance.compareTo(amount) < 0) {
            throw new IllegalStateException("Insufficient balance in " + accountId);
        }
        balance = balance.subtract(amount);
        version++;
    }

    void credit(BigDecimal amount) {
        balance = balance.add(amount);
        version++;
    }

    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in model/Transaction.java in a real project ───
class Transaction {
    private final String txnId;
    private final String accountId;
    private final BigDecimal amount;
    private final LocalDate date;

    Transaction(String txnId, String accountId, BigDecimal amount, LocalDate date) {
        this.txnId = txnId;
        this.accountId = accountId;
        this.amount = amount;
        this.date = date;
    }

    String getTxnId() { return txnId; }
    String getAccountId() { return accountId; }
    BigDecimal getAmount() { return amount; }
    LocalDate getDate() { return date; }
}

// ─── Would be in repository/AccountRepository.java in a real project ───
class AccountRepository {
    private final Map<String, Account> store = new HashMap<>();
    void save(Account a) { store.put(a.getAccountId(), a); }
    Account findById(String id) { return store.get(id); } // returns null if missing
}

// ─── Would be in repository/TransactionRepository.java in a real project ───
class TransactionRepository {
    // A TreeMap keeps transactions sorted by id so cursor paging is a clean seek.
    private final java.util.TreeMap<String, Transaction> store = new java.util.TreeMap<>();
    void save(Transaction t) { store.put(t.getTxnId(), t); }

    // Keyset pagination: return up to `limit` txns with id strictly greater than cursor.
    List<Transaction> findAfter(String accountId, String cursor, int limit) {
        List<Transaction> result = new ArrayList<>();
        var tail = (cursor == null) ? store.values() : store.tailMap(cursor, false).values();
        for (Transaction t : tail) {
            if (t.getAccountId().equals(accountId)) {
                result.add(t);
                if (result.size() == limit) break;
            }
        }
        return result;
    }
}

// ─── Versioned DTO (v2 shape) — hides internal version column ───
record AccountResponse(String accountId, String holderName, BigDecimal balance) {
    static AccountResponse from(Account a) {
        return new AccountResponse(a.getAccountId(), a.getHolderName(), a.getBalance());
    }
}

// ─── Cursor page DTO ───
record PageResponse(List<String> txnIds, String nextCursor, boolean hasMore) {}

// ─── RFC 9457 style exception carrying a structured error body ───
class AccountNotFoundException extends RuntimeException {
    private final String accountId;
    AccountNotFoundException(String accountId) {
        super("Account not found: " + accountId);
        this.accountId = accountId;
    }
    // In Spring this maps to ProblemDetail.forStatusAndDetail(NOT_FOUND, ...).
    String toProblemDetail() {
        return "{\"type\":\"https://bank.example/errors/account-not-found\","
                + "\"title\":\"Account Not Found\",\"status\":404,"
                + "\"detail\":\"" + getMessage() + "\",\"accountId\":\"" + accountId + "\"}";
    }
}

// ─── Idempotency-Key store: remembers the result of the first request per key ───
class IdempotencyStore {
    private final Map<String, String> results = new HashMap<>();
    boolean contains(String key) { return results.containsKey(key); }
    String get(String key) { return results.get(key); }
    void put(String key, String result) { results.put(key, result); }
}

// ─── Service layer: ties all five REST concerns together ───
class BankApiService {
    private static final Logger log = Logger.getLogger(BankApiService.class.getName());
    private final AccountRepository accountRepo;
    private final TransactionRepository txnRepo;
    private final IdempotencyStore idempotency;
    private int transferCounter = 0;

    BankApiService(AccountRepository accountRepo, TransactionRepository txnRepo,
                   IdempotencyStore idempotency) {
        this.accountRepo = accountRepo;
        this.txnRepo = txnRepo;
        this.idempotency = idempotency;
    }

    // Error handling + versioning: returns the v2 DTO or throws a 404 exception.
    AccountResponse getAccount(String accountId) {
        Account a = accountRepo.findById(accountId);
        if (a == null) {
            log.severe(() -> "Account lookup failed for " + accountId);
            throw new AccountNotFoundException(accountId);
        }
        return AccountResponse.from(a);
    }

    // Cursor pagination: fetch forward from the last seen id.
    PageResponse listTransactions(String accountId, String cursor, int limit) {
        List<Transaction> batch = txnRepo.findAfter(accountId, cursor, limit);
        List<String> ids = new ArrayList<>();
        for (Transaction t : batch) ids.add(t.getTxnId());
        String nextCursor = batch.isEmpty() ? null : batch.get(batch.size() - 1).getTxnId();
        boolean hasMore = batch.size() == limit;
        return new PageResponse(ids, nextCursor, hasMore);
    }

    // Idempotency: a repeated key returns the stored result without moving money again.
    String transfer(String idempotencyKey, String fromId, String toId, BigDecimal amount) {
        if (idempotency.contains(idempotencyKey)) {
            log.warning(() -> "Idempotency-Key " + idempotencyKey
                    + " already processed — returning stored result");
            return idempotency.get(idempotencyKey);
        }
        Account from = accountRepo.findById(fromId);
        Account to = accountRepo.findById(toId);
        if (from == null) throw new AccountNotFoundException(fromId);
        if (to == null) throw new AccountNotFoundException(toId);

        from.debit(amount);
        to.credit(amount);
        String transferId = "TXF-" + String.format("%05d", ++transferCounter);
        idempotency.put(idempotencyKey, transferId);
        log.info(() -> "Transfer " + transferId + " Rs." + amount + " " + fromId + " -> " + toId);
        return transferId;
    }
}

// ─── Clean log formatter so demo output is readable ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT  %2$-7s  %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
