// ─── File: src/main/java/com/bank/transfer/TransferDemo.java ───
package com.bank.transfer;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class TransferDemo {

    private static final Logger log = Logger.getLogger(TransferDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Set up the accounts (same characters used across the project).
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        AccountRepository repo = new AccountRepository();
        repo.save(rajesh);
        repo.save(priya);

        // Strategy pattern: register fee strategies by name.
        Map<String, FeeStrategy> strategies = Map.of(
                "regular", new RegularFeeStrategy(),
                "premium", new PremiumFeeStrategy(),
                "promo", new ZeroFeeStrategy());

        // Observer pattern: register listeners that react to completion.
        List<TransferListener> listeners = List.of(
                new AuditListener(), new NotificationListener());

        FxRateClient fxClient = new FxRateClient();
        TransferService service = new TransferService(repo, strategies, listeners, fxClient);

        // Rajesh is a premium customer, so the premium fee strategy applies.
        TransferResult result = service.transfer("SAV2001", "CUR3001",
                new BigDecimal("50000"), "premium");

        log.info(() -> "Final result: " + result);
    }
}

// ─── Would be in model/Account.java in a real project ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    private int version; // internal optimistic-lock column — never exposed

    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }

    void debit(BigDecimal amount) {
        if (balance.compareTo(amount) < 0) {
            throw new IllegalStateException("Insufficient balance in " + accountId);
        }
        balance = balance.subtract(amount);
        version++;
    }

    void credit(BigDecimal amount) {
        balance = balance.add(amount);
        version++;
    }

    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in repository/AccountRepository.java in a real project ───
class AccountRepository {
    private final Map<String, Account> store = new java.util.HashMap<>();
    void save(Account a) { store.put(a.getAccountId(), a); }
    Account findById(String id) {
        Account a = store.get(id);
        if (a == null) throw new IllegalArgumentException("Account not found: " + id);
        return a;
    }
