// ─── Strategy pattern: common interface + three implementations ───
interface FeeStrategy {
    BigDecimal calculateFee(BigDecimal amount);
}

class RegularFeeStrategy implements FeeStrategy {
    public BigDecimal calculateFee(BigDecimal amount) {
        return amount.multiply(new BigDecimal("0.01")).setScale(2, RoundingMode.HALF_UP);
    }
}

class PremiumFeeStrategy implements FeeStrategy {
    public BigDecimal calculateFee(BigDecimal amount) {
        return amount.multiply(new BigDecimal("0.005")).setScale(2, RoundingMode.HALF_UP);
    }
}

class ZeroFeeStrategy implements FeeStrategy {
    public BigDecimal calculateFee(BigDecimal amount) {
        return BigDecimal.ZERO.setScale(2, RoundingMode.HALF_UP);
    }
}

// ─── Builder pattern: immutable result assembled field by field ───
class TransferResult {
    private final String transferId;
    private final String from;
    private final String to;
    private final BigDecimal amount;
    private final BigDecimal fee;
    private final String status;
    private final LocalDateTime at;

    private TransferResult(Builder b) {
        this.transferId = b.transferId;
        this.from = b.from;
        this.to = b.to;
        this.amount = b.amount;
        this.fee = b.fee;
        this.status = b.status;
        this.at = b.at;
    }

    static Builder builder() { return new Builder(); }

    @Override
    public String toString() {
        return "TransferResult{id=" + transferId + ", from=" + from + ", to=" + to
                + ", amount=" + amount + ", fee=" + fee + ", status=" + status + ", at=" + at + "}";
    }

    static class Builder {
        private String transferId;
        private String from;
        private String to;
        private BigDecimal amount;
        private BigDecimal fee;
        private String status;
        private LocalDateTime at = LocalDateTime.now();

        Builder transferId(String v) { this.transferId = v; return this; }
        Builder from(String v) { this.from = v; return this; }
        Builder to(String v) { this.to = v; return this; }
        Builder amount(BigDecimal v) { this.amount = v; return this; }
        Builder fee(BigDecimal v) { this.fee = v; return this; }
        Builder status(String v) { this.status = v; return this; }
        TransferResult build() { return new TransferResult(this); }
    }
}

// ─── Observer pattern: event + listener interface + two listeners ───
class TransferCompletedEvent {
    private final String transferId;
    private final String from;
    private final String to;
    private final BigDecimal amount;

    TransferCompletedEvent(String transferId, String from, String to, BigDecimal amount) {
        this.transferId = transferId;
        this.from = from;
        this.to = to;
        this.amount = amount;
    }

    String transferId() { return transferId; }
    String from() { return from; }
    String to() { return to; }
    BigDecimal amount() { return amount; }
}

interface TransferListener {
    void onTransferCompleted(TransferCompletedEvent event);
}

class AuditListener implements TransferListener {
    private static final Logger log = Logger.getLogger(AuditListener.class.getName());
    public void onTransferCompleted(TransferCompletedEvent e) {
        log.info(() -> "AUDIT: TRANSFER " + e.transferId() + " " + e.from()
                + " -> " + e.to() + " Rs." + e.amount() + " SUCCESS");
    }
}

class NotificationListener implements TransferListener {
    private static final Logger log = Logger.getLogger(NotificationListener.class.getName());
    public void onTransferCompleted(TransferCompletedEvent e) {
        log.info(() -> "SMS to " + e.from() + ": Rs." + e.amount()
                + " transferred to " + e.to() + ". Transfer id " + e.transferId());
    }
}

// ─── Circuit Breaker pattern: a tiny hand-rolled breaker over an external call ───
class FxRateClient {
    private static final Logger log = Logger.getLogger(FxRateClient.class.getName());
    private int failureCount = 0;
    private final int threshold = 3;
    private boolean open = false;
    private final BigDecimal lastKnownRate = new BigDecimal("83.25"); // cached USD/INR

    BigDecimal getRate(String pair) {
        if (open) {
            log.warning(() -> "Circuit OPEN for " + pair + " — returning cached rate");
            return lastKnownRate;
        }
        try {
            return callExternalProvider(pair);
        } catch (RuntimeException ex) {
            failureCount++;
            log.log(Level.SEVERE, "FX provider call failed (" + failureCount + "/" + threshold + ")", ex);
            if (failureCount >= threshold) {
                open = true;
                log.severe("Circuit breaker tripped OPEN for " + pair);
            }
            return lastKnownRate;
        }
    }

    // Simulated flaky external provider.
    private BigDecimal callExternalProvider(String pair) {
        // In the demo we succeed; flip to throw to see the breaker trip.
        return new BigDecimal("83.30");
    }
}

// ─── Service layer: ties every pattern together ───
class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());
    private final AccountRepository repo;
    private final Map<String, FeeStrategy> feeStrategies;
    private final List<TransferListener> listeners;
    private final FxRateClient fxClient;
    private int counter = 0;

    TransferService(AccountRepository repo, Map<String, FeeStrategy> feeStrategies,
                    List<TransferListener> listeners, FxRateClient fxClient) {
        this.repo = repo;
        this.feeStrategies = feeStrategies;
        this.listeners = listeners;
        this.fxClient = fxClient;
    }

    TransferResult transfer(String fromId, String toId, BigDecimal amount, String tier) {
        log.info(() -> "Starting transfer Rs." + amount + " from " + fromId + " to " + toId);

        Account from = repo.findById(fromId);
        Account to = repo.findById(toId);

        // Strategy: pick the fee rule; unknown tier falls back to regular.
        FeeStrategy strategy = feeStrategies.getOrDefault(tier, feeStrategies.get("regular"));
        BigDecimal fee = strategy.calculateFee(amount);
        log.fine(() -> "Fee for tier " + tier + " on Rs." + amount + " = Rs." + fee);

        // Circuit Breaker: safe external call (used here for an FX reference rate).
        BigDecimal rate = fxClient.getRate("USD/INR");
        log.fine(() -> "Reference USD/INR rate = " + rate);

        from.debit(amount.add(fee));
        to.credit(amount);

        String id = "TXF-" + String.format("%05d", ++counter);

        // Observer: notify all listeners of completion.
        TransferCompletedEvent event = new TransferCompletedEvent(id, fromId, toId, amount);
        listeners.forEach(l -> l.onTransferCompleted(event));

        // Builder: assemble the immutable result.
        return TransferResult.builder()
                .transferId(id)
                .from(fromId)
                .to(toId)
                .amount(amount)
                .fee(fee)
                .status("COMPLETED")
                .build();
    }
}

