// ─── File: .../model/FundCategory.java ───
// Sealed interface: ONLY these implementations exist — compiler enforces exhaustive switch
package com.bank.marketplace.model;

public sealed interface FundCategory permits
    FundCategory.Equity, FundCategory.Debt, FundCategory.Liquid, FundCategory.Elss {

    String label();
    double maxExpenseRatio();

    record Equity() implements FundCategory {
        public String label() { return "Equity"; }
        public double maxExpenseRatio() { return 0.0225; }
    }
    record Debt() implements FundCategory {
        public String label() { return "Debt"; }
        public double maxExpenseRatio() { return 0.0200; }
    }
    record Liquid() implements FundCategory {
        public String label() { return "Liquid"; }
        public double maxExpenseRatio() { return 0.0050; }
    }
    record Elss() implements FundCategory {
        public String label() { return "ELSS Tax Saver"; }
        public double maxExpenseRatio() { return 0.0225; }
    }

    // Pattern matching with sealed — exhaustive, no default needed
    static FundCategory from(String name) {
        return switch (name.toUpperCase()) {
            case "EQUITY" -> new Equity();
            case "DEBT" -> new Debt();
            case "LIQUID" -> new Liquid();
            case "ELSS" -> new Elss();
            default -> throw new IllegalArgumentException("Unknown category: " + name);
        };
    }
}
