package com.bank.marketplace.dto;

import com.bank.marketplace.model.Fund;
import java.math.BigDecimal;

public record FundResponse(
    String fundId, String name, String category,
    BigDecimal nav, BigDecimal minInvestment, BigDecimal expenseRatio
) {
    // Factory method: entity → DTO (never expose entity directly)
