// ─── File: .../service/FundService.java ───
package com.bank.marketplace.service;

import com.bank.marketplace.dto.*;
import com.bank.marketplace.exception.FundNotFoundException;
import com.bank.marketplace.model.Fund;
import com.bank.marketplace.strategy.FeeStrategy;
import jakarta.persistence.EntityManager;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;
import java.util.Map;

@Service
@RequiredArgsConstructor
@Slf4j
public class FundService {

    private final EntityManager em;
    private final Map<String, FeeStrategy> feeStrategies;  // Strategy Map — injected by Spring

    @Transactional(readOnly = true)
    public FundResponse getFund(String fundId) {
        Fund fund = em.find(Fund.class, fundId);
        if (fund == null) throw new FundNotFoundException(fundId);
        return FundResponse.from(fund);
    }

    // Cursor pagination (keyset) — fast even on page 10000
    @Transactional(readOnly = true)
    public PageResponse<FundResponse> listFunds(String afterCursor, int size) {
        String jpql = afterCursor == null
            ? "SELECT f FROM Fund f WHERE f.status = 'ACTIVE' ORDER BY f.fundId"
            : "SELECT f FROM Fund f WHERE f.status = 'ACTIVE' AND f.fundId > :cursor ORDER BY f.fundId";

        var query = em.createQuery(jpql, Fund.class).setMaxResults(size + 1);
        if (afterCursor != null) query.setParameter("cursor", afterCursor);

        List<Fund> results = query.getResultList();
        boolean hasMore = results.size() > size;
        List<Fund> page = hasMore ? results.subList(0, size) : results;

        List<FundResponse> items = page.stream().map(FundResponse::from).toList();
        String nextCursor = hasMore ? page.getLast().getFundId() : null;

        return new PageResponse<>(items, items.size(), nextCursor, hasMore);
    }

    // Strategy pattern: fee calculation — selected at runtime from Map
    public BigDecimal calculateFee(String strategyName, BigDecimal amount) {
        FeeStrategy strategy = feeStrategies.getOrDefault(strategyName,
            feeStrategies.get("regular"));  // fallback to regular

        BigDecimal fee = strategy.calculateFee(amount);
        log.info("Fee: {} → Rs.{} (strategy: {})", amount, fee, strategy.getName());
        return fee;
    }
}
