package com.nbi.transfer.service;

import com.nbi.transfer.dto.*;
import com.nbi.transfer.model.Transfer;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

@Service
public class TransferService {
    // Stores the result per idempotency key so repeats do not re-execute.
    private final Map<String, Transfer> byKey = new ConcurrentHashMap<>();

    // POST made idempotent via a key. First call creates; repeats replay.
    public TransferResponse createOnce(String key, TransferRequest r) {
        Transfer existing = byKey.get(key);
        if (existing != null) {
            // Same key seen before → return original, do NOT move money again.
            return new TransferResponse(existing.getId(), existing.getFrom(),
                    existing.getTo(), existing.getAmount(), true);
        }
        Transfer t = new Transfer("TXF-" + UUID.randomUUID().toString().substring(0, 8),
                r.from(), r.to(), r.amount());
        byKey.put(key, t);
        // ... here we would debit/credit accounts exactly once ...
        return new TransferResponse(t.getId(), t.getFrom(), t.getTo(), t.getAmount(), false);
    }
}
```

