@RestController
@RequestMapping("/api/v1/transfers")
public class TransferController {

    private final TransferService service;
    private int requestCount = 0;

    public TransferController(TransferService service) { this.service = service; }

    @PostMapping
    public ResponseEntity<String> create(
            @RequestHeader(value = "Authorization", required = false) String auth,
            @Valid @RequestBody TransferRequest r) {

        if (auth == null) // not authenticated
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Login required"); // 401
        if (!auth.contains("ADMIN") && r.amount().doubleValue() > 500000) // not authorized
            return ResponseEntity.status(HttpStatus.FORBIDDEN).body("Amount needs admin"); // 403
        if (++requestCount > 100) // simplistic rate limit
            return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS).body("Slow down"); // 429

        String txId = service.transfer(r); // may throw → 404 / 422 via advice
        return ResponseEntity.created(URI.create("/api/v1/transfers/" + txId)).body(txId); // 201
    }
}
