package com.nbi.statusx.controller;

import com.nbi.statusx.dto.PaymentRequest;
import com.nbi.statusx.service.PaymentService;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import jakarta.validation.Valid;
import java.net.URI;

@RestController
@RequestMapping("/api/v1")
public class PaymentController {

    private final PaymentService service;
    private int perClientCount = 0;
    public PaymentController(PaymentService service) { this.service = service; }

    // Old endpoint moved permanently → 308 preserves POST method and body (NOT 301).
    @PostMapping("/pay")
    public ResponseEntity<Void> oldPay() {
        return ResponseEntity.status(HttpStatus.PERMANENT_REDIRECT) // 308
                .location(URI.create("/api/v1/payments"))
                .build();
    }

    // New endpoint.
    @PostMapping("/payments")
    public ResponseEntity<String> pay(@Valid @RequestBody PaymentRequest r) {
        // 503 when the whole service's dependency is down (with Retry-After).
        if (!service.isLedgerUp())
            return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE)
                    .header("Retry-After", "30").body("Ledger temporarily down"); // 503
        // 429 when THIS client exceeded its personal rate limit.
        if (++perClientCount > 100)
            return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS)
                    .header("Retry-After", "5").body("Rate limit"); // 429

        return ResponseEntity.created(URI.create("/api/v1/payments/" + service.pay(r)))
                .body("created"); // 201
    }

    // Read-only resource: wrong verb → 405 with Allow header (NOT 400, NOT 501).
    @GetMapping("/payments/{id}")
    public ResponseEntity<String> get(@PathVariable String id) {
        return ResponseEntity.ok("payment " + id);
    }

    @DeleteMapping("/payments/{id}")
    public ResponseEntity<Void> noDelete() {
        return ResponseEntity.status(HttpStatus.METHOD_NOT_ALLOWED)
                .allow(HttpMethod.GET).build(); // 405 + Allow: GET
    }
}
