package com.nbi.problem.exception;

import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import java.net.URI;
import java.util.UUID;

// Returns RFC 9457 Problem Details via Spring's ProblemDetail.
@RestControllerAdvice
public class ProblemExceptionHandler {

    @ExceptionHandler(InsufficientFundsException.class)
    public ProblemDetail insufficient(InsufficientFundsException e) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(
                HttpStatus.UNPROCESSABLE_ENTITY, e.getMessage()); // detail
        pd.setType(URI.create("https://api.nbi.in/problems/insufficient-funds")); // stable, switchable
        pd.setTitle("Insufficient funds");                                        // title
        pd.setInstance(URI.create("/api/v1/transfers/" + UUID.randomUUID()));      // this occurrence
        pd.setProperty("traceId", UUID.randomUUID().toString());                   // extension
        pd.setProperty("balance", e.getBalance());
        pd.setProperty("requested", e.getRequested());
        return pd; // Content-Type: application/problem+json set automatically
    }

    @ExceptionHandler(AccountNotFoundException.class)
    public ProblemDetail notFound(AccountNotFoundException e) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
        pd.setType(URI.create("https://api.nbi.in/problems/account-not-found"));
