    public AccountController(AccountService service) { this.service = service; }

    @GetMapping("/{id}")
    public ResponseEntity<EntityModel<AccountDto>> get(@PathVariable String id) {
        return service.get(id).map(dto -> {
            EntityModel<AccountDto> model = EntityModel.of(dto);
            // Always available links:
            model.add(linkTo(methodOn(AccountController.class).get(id)).withSelfRel());
            model.add(linkTo(methodOn(AccountController.class).transactions(id)).withRel("transactions"));
            // STATE-DRIVEN links: present only when the action is actually allowed.
            if (dto.isActive()) {
                model.add(linkTo(methodOn(AccountController.class).transfer(id)).withRel("transfer"));
                model.add(linkTo(methodOn(AccountController.class).freeze(id)).withRel("freeze"));
            } else {
                model.add(linkTo(methodOn(AccountController.class).unfreeze(id)).withRel("unfreeze"));
            }
            return ResponseEntity.ok(model);
        }).orElse(ResponseEntity.notFound().build());
    }

