package com.nbi.secure.security;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import java.util.*;

@Service
public class JwtService {
    private final String secret;
    // Secret INJECTED from config/env — never hardcoded in source.
    public JwtService(@Value("${app.jwt.secret:dev-secret}") String secret) {
        this.secret = secret;
    }

    // Simplified verify: in production use a real JWT library + signature check.
    public Optional<Map<String, Object>> verify(String header) {
        if (header == null || !header.startsWith("Bearer ")) return Optional.empty();
        String token = header.substring(7);
        // Demo tokens: "CUST:rajesh" or "ADMIN:ops". Real code verifies signature/expiry/issuer.
        if (token.startsWith("CUST:")) return Optional.of(Map.of("sub", token.substring(5), "roles", List.of("CUSTOMER")));
        if (token.startsWith("ADMIN:")) return Optional.of(Map.of("sub", token.substring(6), "roles", List.of("ADMIN")));
        return Optional.empty(); // invalid → caller returns 401
    }
}
