// ─── File: src/main/java/com/bank/hpp/filter/ParameterPollutionFilter.java ───
package com.bank.hpp.filter;

import jakarta.servlet.*;
import jakarta.servlet.http.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;
import java.io.IOException;
import java.util.List;
import java.util.Map;

// Runs before the controller. Rejects any single-valued parameter sent
// more than once, closing the HPP gap at the earliest possible point.
@Component
@Order(1)
public class ParameterPollutionFilter implements Filter {

    private static final Logger log = LoggerFactory.getLogger(ParameterPollutionFilter.class);

    // Parameters that must appear at most once. Sending them twice is HPP.
    private static final List<String> SINGLE_VALUED =
            List.of("accountType", "role", "amount");

    @Override
    public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain)
            throws IOException, ServletException {

        HttpServletRequest request = (HttpServletRequest) req;
        HttpServletResponse response = (HttpServletResponse) res;

        for (Map.Entry<String, String[]> entry : request.getParameterMap().entrySet()) {
            String name = entry.getKey();
            String[] values = entry.getValue();
            if (SINGLE_VALUED.contains(name) && values.length > 1) {
                // Do NOT guess which value wins — reject the ambiguity.
                log.warn("HPP blocked: parameter '{}' sent {} times from {}",
                        name, values.length, request.getRemoteAddr());
                response.setStatus(400);
                response.setContentType("application/json");
                response.getWriter().write(
                        "{\"error\":\"DUPLICATE_PARAMETER\",\"field\":\"" + name + "\"}");
                return;
            }
        }
        chain.doFilter(req, res);
    }
}
