package com.bank.audit.audit;

import java.time.Instant;

// Immutable value object built via the builder pattern.
public final class AuditRecord {
    private final String actor;
    private final String action;
    private final String target;
    private final String outcome;
    private final String correlationId;
    private final Instant timestamp;

    private AuditRecord(Builder b) {
        this.actor = b.actor;
        this.action = b.action;
        this.target = b.target;
        this.outcome = b.outcome;
        this.correlationId = b.correlationId;
        this.timestamp = b.timestamp;
    }

    public String fingerprint() {
        // Deterministic string used to compute the tamper-evident hash.
        return actor + "|" + action + "|" + target + "|" + outcome + "|"
                + correlationId + "|" + timestamp;
    }

    public String getActor() { return actor; }
    public String getOutcome() { return outcome; }

    public static Builder builder() { return new Builder(); }

    public static final class Builder {
        private String actor, action, target, outcome, correlationId;
        private Instant timestamp;
        public Builder actor(String v) { this.actor = v; return this; }
        public Builder action(String v) { this.action = v; return this; }
        public Builder target(String v) { this.target = v; return this; }
        public Builder outcome(String v) { this.outcome = v; return this; }
        public Builder correlationId(String v) { this.correlationId = v; return this; }
        public Builder timestamp(Instant v) { this.timestamp = v; return this; }
        public AuditRecord build() { return new AuditRecord(this); }
    }
}
