package com.bank.history.repository;

import com.bank.history.model.Transaction;
import org.springframework.data.domain.*;
import org.springframework.data.jpa.repository.*;
import org.springframework.data.repository.query.Param;
import java.util.List;

public interface TransactionRepository extends JpaRepository<Transaction, Long> {

    // OFFSET pagination: Spring Data applies LIMIT/OFFSET and runs a COUNT.
    Page<Transaction> findByAccountId(String accountId, Pageable pageable);

    // KEYSET pagination: fetch the next slice AFTER the last seen id, using
    // the index. No OFFSET, so it stays fast at any depth. We order by id DESC
    // (newest first) and ask for ids strictly smaller than the cursor.
    @Query("SELECT t FROM Transaction t WHERE t.accountId = :accountId " +
           "AND (:cursor IS NULL OR t.id < :cursor) ORDER BY t.id DESC")
    List<Transaction> findKeyset(@Param("accountId") String accountId,
                                 @Param("cursor") Long cursor,
                                 Pageable limit);
}
