package com.bank.query.filter;

import com.bank.query.model.Transaction;
import org.springframework.data.jpa.domain.Specification;
import java.math.BigDecimal;

// Type-safe predicates. Field names come from the entity metamodel, never
// from raw client strings, so there is no injection surface.
public final class TransactionSpecifications {

    private TransactionSpecifications() { }

    public static Specification<Transaction> accountId(String accountId) {
        return (root, q, cb) -> cb.equal(root.get("accountId"), accountId);
    }

    public static Specification<Transaction> status(String status) {
        return status == null ? null
                : (root, q, cb) -> cb.equal(root.get("status"), status);
    }

    public static Specification<Transaction> type(String type) {
        return type == null ? null
                : (root, q, cb) -> cb.equal(root.get("type"), type);
    }

    public static Specification<Transaction> minAmount(BigDecimal min) {
        return min == null ? null
                : (root, q, cb) -> cb.greaterThanOrEqualTo(root.get("amount"), min);
    }
}
