// ─── File: src/main/java/com/bank/patterns/server/AccountServiceImpl.java ───
package com.bank.patterns.server;

import com.bank.patterns.gen.*;
import io.grpc.stub.StreamObserver;
import net.devh.boot.grpc.server.service.GrpcService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@GrpcService
public class AccountServiceImpl extends AccountServiceGrpc.AccountServiceImplBase {

    private static final Logger log = LoggerFactory.getLogger(AccountServiceImpl.class);

    // 1) UNARY — one request, one response.
    @Override
    public void getBalance(AccountRef ref, StreamObserver<Balance> obs) {
        log.info("Unary getBalance {}", ref.getNumber());
        obs.onNext(Balance.newBuilder().setBalancePaise(100_000_000).build());
        obs.onCompleted();
    }

    // 2) SERVER STREAMING — one request, many responses.
    @Override
    public void streamStatement(AccountRef ref, StreamObserver<Transaction> obs) {
        log.info("Server streaming statement {}", ref.getNumber());
        for (int i = 1; i <= 3; i++) {                    // imagine thousands
            obs.onNext(Transaction.newBuilder()
                    .setId("T" + i).setAmountPaise(i * 100_000L).build());
        }
        obs.onCompleted();                                // done streaming
    }

    // 3) CLIENT STREAMING — many requests, one response at the end.
    @Override
    public StreamObserver<Cheque> depositCheques(StreamObserver<DepositSummary> obs) {
        return new StreamObserver<>() {
            long total = 0; int count = 0;
            @Override public void onNext(Cheque c) {
                total += c.getAmountPaise(); count++;
                log.info("Received cheque {} ({} paise)", c.getChequeNo(), c.getAmountPaise());
            }
            @Override public void onError(Throwable t) { log.error("deposit failed", t); }
            @Override public void onCompleted() {
                obs.onNext(DepositSummary.newBuilder()
                        .setCount(count).setTotalPaise(total).build());
                obs.onCompleted();                        // single summary reply
            }
        };
    }

    // 4) BIDIRECTIONAL STREAMING — both sides stream independently.
    @Override
    public StreamObserver<Order> liveTrading(StreamObserver<Fill> obs) {
        return new StreamObserver<>() {
            @Override public void onNext(Order order) {
                log.info("Order {} x{}", order.getSymbol(), order.getQty());
                // Respond with a fill whenever we like — not lock-stepped.
                obs.onNext(Fill.newBuilder()
                        .setSymbol(order.getSymbol()).setQty(order.getQty())
                        .setPricePaise(245_050).build());
            }
            @Override public void onError(Throwable t) { log.error("trading stream error", t); }
            @Override public void onCompleted() { obs.onCompleted(); }
        };
    }
}
