public class TradingWebSocketHandler extends TextWebSocketHandler {

    private static final Logger log = LoggerFactory.getLogger(TradingWebSocketHandler.class);

    @Override
    public void afterConnectionEstablished(WebSocketSession session) {
        log.info("Trading session opened: {}", session.getId());
    }

    // Client → server: an order arrives. Server → client: send a fill back.
    @Override
    protected void handleTextMessage(WebSocketSession session, TextMessage message)
            throws Exception {
        String order = message.getPayload();          // e.g. {"symbol":"RELIANCE","qty":100}
        log.info("Order received: {}", order);
        // Respond on the SAME connection whenever we like — two-way.
        session.sendMessage(new TextMessage(
                "{\"type\":\"FILL\",\"order\":" + order + ",\"pricePaise\":245050}"));
    }

    @Override
    public void afterConnectionClosed(WebSocketSession session, CloseStatus status) {
        log.info("Trading session closed: {} ({})", session.getId(), status);
    }
}
